#include <stdint.h>
#include <stdio.h>
#include <unistd.h>

int main(void) {
    long system_page_size = sysconf(_SC_PAGESIZE);
    size_t demo_page_size = 4096;

    /* 内部碎片演示 */
    size_t object_size = 10 * 1024;
    size_t page_count = (object_size + demo_page_size - 1) / demo_page_size;
    size_t internal_waste = page_count * demo_page_size - object_size;

    /* 虚拟地址拆分：VPN + 页内偏移 */
    uintptr_t virtual_address = 0x12345abc;
    uintptr_t vpn = virtual_address / demo_page_size;
    uintptr_t offset = virtual_address % demo_page_size;

    /* 分段 limit 检查：offset 越界即段保护失败 */
    size_t segment_limit = 8192;
    size_t segment_offset_ok = 9000;
    const char *result1 = segment_offset_ok <= segment_limit ? "ok" : "segmentation fault";
    size_t segment_offset_bad = 8193;
    const char *result2 = segment_offset_bad <= segment_limit ? "ok" : "segmentation fault";

    /* 大页与普通页关系 */
    size_t huge_page = 2 * 1024 * 1024;
    size_t normal_pages_per_huge = huge_page / demo_page_size;

    printf("system page size: %ld bytes\n", system_page_size);
    printf("10KiB object: %zu pages, last page uses %zuB of %zuB, waste=%zuB\n",
           page_count, object_size % demo_page_size, demo_page_size, internal_waste);
    printf("VA 0x%lx => VPN=%lu, offset=%lu\n",
           (unsigned long)virtual_address, (unsigned long)vpn, (unsigned long)offset);
    printf("segment offset=%zu, limit=%zu => %s\n", segment_offset_ok, segment_limit, result1);
    printf("segment offset=%zu, limit=%zu => %s\n", segment_offset_bad, segment_limit, result2);
    printf("2MiB huge page = %zu x 4KB pages\n", normal_pages_per_huge);

    return page_count == 3 && internal_waste == 2048 && normal_pages_per_huge == 512 ? 0 : 1;
}
